"""One streaming traversal of finalized G-code (#1779): same answers as the separate passes, never stale."""
import json
import random

import pytest

from print_handy.core import slice_guard as sg

SAMPLES = [
    "",
    "; generated by OrcaSlicer 2.3\n; brim_type = no_brim\nT0\nG1 X1 Y1\n  T2 ; swap\n; machine_start_gcode = START MESH=abc\n",
    "; filament_settings_id = \"Hermes slot 1 PLA\"\r\nT1\r\n;no equals\r\n; print_host = a=b\r\nt3\r\n",
    "; print_host = x\rT1\r; post_process = y\n",              # lone CR is a line break for splitlines
    "T1\u2028; print_host = z\n\x0cT4\n",                      # other splitlines separators
    "G1 X1\nT0 extra\n   t7   ;c\n;;host_type=\nX; host_type = q\n; host_type = q=1\n",
    "; printer_technology = FFF",                              # no trailing newline
]


def _random_text(rng):
    pieces = ["T%d" % rng.randint(0, 9), " t%d ; c" % rng.randint(0, 9), "; print_host = h%d" % rng.randint(0, 3),
              "; machine_end_gcode = M104 S0", "G1 X%d Y%d" % (rng.randint(0, 9), rng.randint(0, 9)),
              ";x=y", "  ; host_type = a", "T", "TT1", "", "\r", "; post_process = p\r"]
    seps = ["\n", "\r\n", "\n", "\r", "\u2028"]
    return "".join(rng.choice(pieces) + rng.choice(seps) for _ in range(rng.randint(0, 40)))


@pytest.mark.parametrize("text", SAMPLES + [_random_text(random.Random(i)) for i in range(300)])
def test_scan_equals_the_separate_passes(text, tmp_path):
    scan = sg.scan_gcode(text)
    assert set(scan.tools) == sg.tool_numbers(text)
    assert list(scan.comments) == [ln for ln in text.splitlines() if ln.startswith(";") and "=" in ln]
    assert scan.protected == sg._effective_config(text)
    assert sg._effective_config(text, scan) == sg._effective_config(text)


def test_scan_covers_only_its_own_text():
    text = "; print_host = a\nT1\n"
    scan = sg.scan_gcode(text)
    assert scan.covers(text)
    assert not scan.covers("; print_host = b\nT1\n")      # edited text is never answered from the scan
    assert not scan.covers("".join(list(text)))          # an equal copy is a different object: rescan


def test_post_slice_ignores_a_scan_of_other_text(tmp_path):
    clean = "; generated by OrcaSlicer\n; filament_settings_id = \"x\"\nG1 X1 Y1\n"
    bad = clean + "T9\n"
    stale = sg.scan_gcode(clean)
    own = sg.post_slice(bad, scan=stale, filament_slots=4, tool_slots={}, bed=(220, 220), templates=tmp_path)
    ref = sg.post_slice(bad, filament_slots=4, tool_slots={}, bed=(220, 220), templates=tmp_path)
    assert own.blocked == ref.blocked and any("T9" in b for b in ref.blocked)


def test_post_slice_result_is_the_same_with_and_without_a_scan(tmp_path):
    text = "\n".join(["; generated by OrcaSlicer", "; brim_type = outer_only", "T0", "G1 X5 Y5", "T3", "G1 X400 Y5", ""])
    a = sg.post_slice(text, filament_slots=4, tool_slots={0: 1}, bed=(220, 220), templates=tmp_path)
    b = sg.post_slice(text, scan=sg.scan_gcode(text), filament_slots=4, tool_slots={0: 1}, bed=(220, 220), templates=tmp_path)
    assert json.dumps(a.as_dict(), sort_keys=True) == json.dumps(b.as_dict(), sort_keys=True)
    assert a.blocked


def test_baseline_uses_a_scan_but_blocks_the_same_edit(tmp_path):
    artifact = tmp_path / "a.gcode"
    artifact.write_text("; print_host = 10.0.0.1\n; host_type = moonraker\nG1 X1\n" + "; pad\n" * 200)
    base = tmp_path / "base.json"
    sg.approve_baseline(artifact, path=base)
    scan = sg.scan_gcode(artifact.read_text())
    assert sg.enforce_approved_baseline(artifact, path=base, scan=scan).status == "ok"
    artifact.write_text(artifact.read_text().replace("10.0.0.1", "6.6.6.6"))
    assert sg.enforce_approved_baseline(artifact, path=base).status == "blocked"


def test_same_size_rewrite_with_restored_mtime_is_not_trusted(tmp_path):
    import os
    artifact = tmp_path / "a.gcode"
    text = "; print_host = 10.0.0.1\n; host_type = moonraker\nG1 X1\n" + "; pad\n" * 200
    artifact.write_text(text)
    before = artifact.stat()
    assert sg.artifact_matches_text(artifact, text)
    artifact.write_text(text.replace("10.0.0.1", "66.6.6.6"))  # same length
    os.utime(artifact, ns=(before.st_atime_ns, before.st_mtime_ns))
    after = artifact.stat()
    assert (after.st_size, after.st_mtime_ns) == (before.st_size, before.st_mtime_ns)
    assert not sg.artifact_matches_text(artifact, text)
    assert not sg.artifact_matches_text(tmp_path / "missing.gcode", text)
